/**
 * Represents the options the sleigh compiler uses
 */
public class SleighCompileOptions {
	public File inputFile;
	public File outputFile;
	public bool allMode = false;
	public File allDir;

	public Map<string, string> preprocs = new();
	public bool unnecessaryPcodeWarning = false;
	public bool lenientConflict = true;
	public bool allCollisionWarning = false;
	public bool allNopWarning = false;
	public bool deadTempWarning = false;
	public bool enforceLocalKeyWord = false;
	public bool unusedFieldWarning = false;
	public bool caseSensitiveRegisterNames = false;
	public bool debugOutput = false;

	public static void usage() {
		// @formatter:off
		Msg.info(typeof(SleighCompileOptions), "Usage: sleigh [options...] [<infile.slaspec> [<outfile.sla>] | -a <directory-path>]");
		Msg.info(typeof(SleighCompileOptions), "    sleigh [options...] <infile.slaspec> [<outfile.sla>]");
		Msg.info(typeof(SleighCompileOptions), "       <infile.slaspec>   source slaspec file to be compiled");
		Msg.info(typeof(SleighCompileOptions), "       <outfile.sla>      optional output sla file (infile.sla assumed)");
		Msg.info(typeof(SleighCompileOptions), "  or");
		Msg.info(typeof(SleighCompileOptions), "    sleigh [options...] -a <directory-path>");
		Msg.info(typeof(SleighCompileOptions), "       <directory-path>   directory to have all slaspec files compiled");
		Msg.info(typeof(SleighCompileOptions), "  options:");
		Msg.info(typeof(SleighCompileOptions), "   -x                turns on parser debugging");
		Msg.info(typeof(SleighCompileOptions), "   -y                write .sla using XML debug format");
		Msg.info(typeof(SleighCompileOptions), "   -u                print warnings for unnecessary pcode instructions");
		Msg.info(typeof(SleighCompileOptions), "   -l                report pattern conflicts");
		Msg.info(typeof(SleighCompileOptions), "   -n                print warnings for all NOP constructors");
		Msg.info(typeof(SleighCompileOptions), "   -t                print warnings for dead temporaries");
		Msg.info(typeof(SleighCompileOptions), "   -e                enforce use of 'local' keyword for temporaries");
		Msg.info(typeof(SleighCompileOptions), "   -c                print warnings for all constructors with colliding operands");
