		Msg.info(typeof(SleighCompileOptions), "   -dMODULE          defines a preprocessor macro MODULE with a value of its module path (option may be repeated)");
		Msg.info(typeof(SleighCompileOptions), "   -i <options-file> inject options from specified file");
